const h3 = require('h3-js');

// LatLng to H3 index at resolution 9
const lat = 37.775938728915946;
const lng = -122.41795063018799;
const res = 9; // choose resolution based on required cell size
const cell = h3.geoToH3(lat, lng, res);
console.log('H3 cell:', cell);

// k-ring: get neighbors up to radius 2
const neighbors = h3.kRing(cell, 2);
console.log('Neighbors:', neighbors);

// polyfill: get cells that cover a polygon (e.g., map tile)
const polygon = [
  [37.77, -122.43],
  [37.78, -122.43],
  [37.78, -122.41],
  [37.77, -122.41]
];
const cells = h3.polyfill(polygon, res);
console.log('Polyfill count:', cells.length);

